-- An INSERT ... ON CONFLICT's plan shows its resolution and arbiter indexes
-- (in OID order), and EXPLAIN ANALYZE its inserted and conflicting tuples;
-- a dynamic EXPLAIN ANALYZE in PL/pgSQL runs as a new command, seeing the
-- writes before it; min and max of a NOT NULL column need no IS NOT NULL.
CREATE TABLE oc940 (id int PRIMARY KEY, k int, v text);
CREATE UNIQUE INDEX oc940_k ON oc940 (k);
CREATE UNIQUE INDEX oc940_k2 ON oc940 (k);
INSERT INTO oc940 VALUES (1, 1, 'a'), (2, 2, 'b');
EXPLAIN (COSTS OFF) INSERT INTO oc940 VALUES (1, 5, 'x') ON CONFLICT (id) DO UPDATE SET v = 'y';
EXPLAIN (COSTS OFF) INSERT INTO oc940 VALUES (3, 1, 'x') ON CONFLICT (k) DO NOTHING;
EXPLAIN (COSTS OFF) INSERT INTO oc940 VALUES (3, 1, 'x') ON CONFLICT DO NOTHING;
EXPLAIN (COSTS OFF, FORMAT JSON) INSERT INTO oc940 VALUES (3, 1, 'x') ON CONFLICT (k) DO NOTHING;
EXPLAIN (COSTS OFF, FORMAT XML) INSERT INTO oc940 VALUES (3, 1, 'x') ON CONFLICT ON CONSTRAINT oc940_pkey DO NOTHING;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) INSERT INTO oc940 VALUES (1, 7, 'x'), (4, 4, 'z') ON CONFLICT (id) DO UPDATE SET v = 'y';
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) INSERT INTO oc940 SELECT g, g, 'n' FROM generate_series(3, 6) g ON CONFLICT DO NOTHING;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF, FORMAT JSON) INSERT INTO oc940 VALUES (2, 9, 'x') ON CONFLICT (id) DO NOTHING;
CREATE TABLE cc940 (id int);
INSERT INTO cc940 VALUES (1), (2);
CREATE FUNCTION twice940() RETURNS SETOF text LANGUAGE plpgsql AS $$
DECLARE line text;
BEGIN
  FOR line IN EXECUTE 'EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) DELETE FROM cc940 WHERE id = 1' LOOP RETURN NEXT line; END LOOP;
  FOR line IN EXECUTE 'EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF, SUMMARY OFF, BUFFERS OFF) DELETE FROM cc940 WHERE id = 1' LOOP RETURN NEXT line; END LOOP;
  RETURN NEXT (SELECT count(*)::text FROM cc940);
END $$;
SELECT twice940();
ANALYZE oc940;
EXPLAIN (COSTS OFF) SELECT max(id) FROM oc940;
EXPLAIN (COSTS OFF) SELECT min(k) FROM oc940;
DROP FUNCTION twice940();
DROP TABLE oc940, cc940;
